+package org.apache.druid.jackson;
+
+import com.fasterxml.jackson.core.JsonFactory;
+import com.fasterxml.jackson.core.JsonParseException;
+import com.fasterxml.jackson.core.JsonParser;
+import com.fasterxml.jackson.core.JsonToken;
+import com.fasterxml.jackson.core.SerializableString;
+import com.fasterxml.jackson.core.util.JsonParserDelegate;
+
+import java.io.DataInput;
+import java.io.File;
+import java.io.IOException;
+import java.io.InputStream;
+import java.io.Reader;
+import java.net.URL;
+
+/**
+ * JsonFactory that rejects empty JSON field names to prevent injectable-parameter bypasses.
+ */
+public class NoEmptyFieldNameJsonFactory extends JsonFactory
+{
+  @Override
+  public JsonParser createParser(File f) throws IOException
+  {
+    return wrap(super.createParser(f));
+  }
+
+  @Override
+  public JsonParser createParser(URL url) throws IOException
+  {
+    return wrap(super.createParser(url));
+  }
+
+  @Override
+  public JsonParser createParser(InputStream in) throws IOException
+  {
+    return wrap(super.createParser(in));
+  }
+
+  @Override
+  public JsonParser createParser(Reader r) throws IOException
+  {
+    return wrap(super.createParser(r));
+  }
+
+  @Override
+  public JsonParser createParser(byte[] data) throws IOException
+  {
+    return wrap(super.createParser(data));
+  }
+
+  @Override
+  public JsonParser createParser(byte[] data, int offset, int len) throws IOException
+  {
+    return wrap(super.createParser(data, offset, len));
+  }
+
+  @Override
+  public JsonParser createParser(String content) throws IOException
+  {
+    return wrap(super.createParser(content));
+  }
+
+  @Override
+  public JsonParser createParser(char[] content) throws IOException
+  {
+    return wrap(super.createParser(content));
+  }
+
+  @Override
+  public JsonParser createParser(char[] content, int offset, int len) throws IOException
+  {
+    return wrap(super.createParser(content, offset, len));
+  }
+
+  @Override
+  public JsonParser createParser(DataInput in) throws IOException
+  {
+    return wrap(super.createParser(in));
+  }
+
+  private JsonParser wrap(JsonParser parser)
+  {
+    return new JsonParserDelegate(parser)
+    {
+      @Override
+      public JsonToken nextToken() throws IOException
+      {
+        JsonToken token = super.nextToken();
+        enforceNoEmptyFieldName(token, getCurrentName());
+        return token;
+      }
+
+      @Override
+      public String nextFieldName() throws IOException
+      {
+        String name = super.nextFieldName();
+        enforceNoEmptyFieldName(JsonToken.FIELD_NAME, name);
+        return name;
+      }
+
+      @Override
+      public boolean nextFieldName(SerializableString str) throws IOException
+      {
+        boolean matched = super.nextFieldName(str);
+        enforceNoEmptyFieldName(JsonToken.FIELD_NAME, getCurrentName());
+        return matched;
+      }
+
+      private void enforceNoEmptyFieldName(JsonToken token, String name) throws JsonParseException
+      {
+        if (token == JsonToken.FIELD_NAME && name != null && name.isEmpty()) {
+          throw new JsonParseException(this, "Empty JSON field names are not allowed");
+        }
+      }
+    };
+  }
+}
